// Version A
async function fetchResource(url: string): Promise<{ ok: boolean; status: number; body: any }> {
  const res = await fetch(url);
  const body = await res.json();
  return { ok: res.ok, status: res.status, body };
}

// Version B
async function fetchResourceThrow(url: string): Promise<any> {
  const res = await fetch(url);
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  return await res.json();
}
